(()=>{'use strict';const $=id=>document.getElementById(id),s=document.createElement('section');s.id='mxpdPanel';
const input=(id,label,value='')=>`<label>${label}<input id="${id}" type="number" step="any" value="${value}"></label>`;
s.innerHTML=`<h2>Mₓₚᴅ · Equivalent XPD margin</h2><p>Clear-air/multipath ตาม ITU-R P.530-18 §4.1 · เติม C₀/I ภายหลังได้</p><div class="fields">${input('mxXA','Antenna XPD A (dB)')}${input('mxXB','Antenna XPD B (dB)')}${input('mxFA','XPIF ภาครับ A (dB)',20)}${input('mxFB','XPIF ภาครับ B (dB)',20)}<label>โครงสร้าง H/V<select id="mxLayout"><option value="single">จานร่วม Dual-polarized ต่อสถานี</option><option value="separate">จาน H/V แยกกันต่อสถานี</option></select></label>${input('mxSA','ระยะห่างแนวดิ่งจาน H/V ที่ A (m)')}${input('mxSB','ระยะห่างแนวดิ่งจาน H/V ที่ B (m)')}<label>ที่มา XPIF<input id="mxSource" value="สมมติ 20 dB ตามค่าทั่วไปใน ITU ไม่ใช่สเปกยืนยัน Huawei"></label></div><p>XPIF ใช้เมื่อ XPIC ของลิงก์ Enable เท่านั้น · ค่าในส่วนนี้ใช้สำหรับ Mₓₚᴅ</p><button type="button" id="mxUse30">ใช้ XPD 30 dB ทั้งสองฝั่งตามจาน 0.9 m ที่ส่งมา</button><p class="note">ใช้เมื่อจานทั้งสองฝั่งตรงกับสเปกที่ส่งมา รุ่นอื่นให้กรอก XPD ของรุ่นนั้น</p><h3>C₀/I ต่อ modulation ที่เกณฑ์ BER เดียวกับลิงก์</h3><p>เป็น C/I ขั้นต่ำก่อนประโยชน์ XPIC ไม่ใช่ RX จริง − RX sensitivity · ว่าง = รอข้อมูล ไม่แทนด้วย 0</p><div style="overflow:auto"><table><thead><tr><th>Modulation</th><th>C₀/I ภาครับ A (dB)</th><th>C₀/I ภาครับ B (dB)</th></tr></thead><tbody id="mxModes"></tbody></table></div><p id="mxStatus" role="status">คำนวณลิงก์ก่อนเพื่อโหลดพารามิเตอร์</p><div id="mxOutput"></div>`;
$('dishSizing').before(s);let base=null,path=null,modes=[],signature='';const n=id=>$(id).value.trim()===''?null:Number($(id).value);
function assess(){const separate=$('mxLayout').value==='separate';$('mxSA').disabled=$('mxSB').disabled=!separate;if(!base)return;const mp=MWAvailability.multipath(base,path,base.availability||{});const v=MWXPD.calculate({xpdA:n('mxXA'),xpdB:n('mxXB'),freq:base.freq,p0Percent:mp.p0,layout:$('mxLayout').value,spacingA:n('mxSA'),spacingB:n('mxSB'),xpic:base.xpic==='Enable',xpifA:n('mxFA'),xpifB:n('mxFB'),xpifSource:$('mxSource').value,ber:base.ber,note:mp.note||'',modes:modes.map((m,i)=>({name:m.name,ciA:n('mxCA'+i),ciB:n('mxCB'+i)}))});if(mp.error)v.errors.push(mp.error);if(path.missing||!(path.minLOS>0)||!path.clear)v.errors.push('ต้องตรวจ DEM และ LOS/Fresnel ให้ผ่านก่อน');base.mxpd=v;$('mxOutput').innerHTML=MWXPD.html(v);$('mxStatus').textContent=v.errors.length?'ยังคำนวณไม่ได้ ตรวจข้อมูลด้านล่าง':v.rows.some(r=>r.margin===null)?'คำนวณ XPD₀, η, Q และ C แล้ว · รอ C/I หรือ XPIF':'คำนวณ Mₓₚᴅ แล้ว · แนบผลในรายงาน';}
s.addEventListener('input',assess);$('mxUse30').onclick=()=>{$('mxXA').value=$('mxXB').value='30';assess()};assess();
globalThis.MWXPDUI={invalidate(){if(base)delete base.mxpd;base=null;path=null;$('mxOutput').innerHTML='';$('mxStatus').textContent='กรุณาคำนวณลิงก์ใหม่ก่อนใช้ผล Mₓₚᴅ'},onCalculated(c,r){base=c;path=r;modes=MWDish.modes(c);const sig=JSON.stringify([c.freq,c.bandwidth,c.ber,c.a.radio,c.b.radio,modes]);if(sig!==signature){signature=sig;$('mxModes').replaceChildren(...modes.map((m,i)=>{const tr=document.createElement('tr'),name=document.createElement('td');name.textContent=m.name;tr.append(name);for(const side of ['A','B']){const td=document.createElement('td'),el=document.createElement('input');el.type='number';el.step='any';el.id='mxC'+side+i;el.placeholder='รอ C/I';el.setAttribute('aria-label','C/I '+side+' '+m.name);td.append(el);tr.append(td)}return tr}))}for(const side of ['A','B'])if(Number.isFinite(c[side.toLowerCase()].xpd))$('mxX'+side).value=c[side.toLowerCase()].xpd;assess()}};
})();
